import{V as e,Z as t,et as n,ht as r,nt as i,rt as a,tt as o,yt as s}from"./chunks/framework.b40SKNeR.js";var c=JSON.parse(`{"title":"Upgrading","description":"Upgrade Citizen without breaking the pages your wiki still has cached","frontmatter":{"title":"Upgrading","description":"Upgrade Citizen without breaking the pages your wiki still has cached"},"headers":[],"relativePath":"guide/upgrading.md","filePath":"guide/upgrading.md","lastUpdated":1785300783000}`),l={name:`guide/upgrading.md`};function u(e,c,l,u,d,f){let p=s(`CopyOrDownloadAsMarkdownButtons`);return r(),n(`div`,null,[c[0]||=t(`div`,{style:{display:`none`},hidden:`true`,"aria-hidden":`true`,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /v3.20/guide/upgrading.md for this page in Markdown format`,-1),c[1]||=t(`h1`,{id:`upgrading`,tabindex:`-1`},[i(`Upgrading `),t(`a`,{class:`header-anchor`,href:`#upgrading`,"aria-label":`Permalink to “Upgrading”`},`​`)],-1),a(p),c[2]||=o(`<p>Citizen serves CSS and JS fresh on every page view, but wikis cache HTML — in the parser cache, CDN or Varnish layers, and <code>$wgUseFileCache</code>. After an upgrade, cached pages generated by the old version meet the new styles, which can break their appearance until every cache has expired or been purged.</p><h2 id="start-with-the-release-cache-status" tabindex="-1">Start with the release cache status <a class="header-anchor" href="#start-with-the-release-cache-status" aria-label="Permalink to “Start with the release cache status”">​</a></h2><p>Releases state a cache status in their <a href="./../changelogs/">notes</a>, near the top and above the highlights — a one-line note, or a warning callout when a purge is needed. Check it first: it tells you whether the rest of this page applies at all.</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means for you</th></tr></thead><tbody><tr><td><code>clean</code></td><td>No cached-HTML impact. Upgrade as usual — nothing else here applies.</td></tr><tr><td><code>covered by compat</code></td><td>Follow the steps below so cached pages stay readable.</td></tr><tr><td><code>purge required</code></td><td>Some pages cannot be bridged by styles alone, so plan a <a href="#clearing-the-old-cache">cache clear</a>. The steps below still cover everything else.</td></tr></tbody></table><p>Older releases predate this convention. If the notes state no status, treat the release as <code>covered by compat</code> — or as <code>purge required</code> if they mention purging. Moving up several releases at once? Go with the strictest status of the bunch.</p><h2 id="plan-ahead" tabindex="-1">Plan ahead <a class="header-anchor" href="#plan-ahead" aria-label="Permalink to “Plan ahead”">​</a></h2><p>If you know an upgrade is coming, lower <code>$wgParserCacheExpireTime</code> a few days early. It applies to entries already in the cache, not just new ones, so pages start re-parsing straight away and normal traffic works through the long tail before you deploy instead of after. Write the old value down first, and put it back once the upgrade has settled.</p><h2 id="upgrade-steps" tabindex="-1">Upgrade steps <a class="header-anchor" href="#upgrade-steps" aria-label="Permalink to “Upgrade steps”">​</a></h2><h3 id="_1-turn-the-compat-flag-on" tabindex="-1">1. Turn the compat flag on <a class="header-anchor" href="#_1-turn-the-compat-flag-on" aria-label="Permalink to “1. Turn the compat flag on”">​</a></h3><p>Set <a href="./../config/#wgcitizencompat"><code>$wgCitizenCompat</code></a> <strong>before</strong> you upgrade. It is safe to set on a version that predates it — nothing reads the setting until the new code is in place. While it is on, Citizen also serves the styles recent releases retired, so HTML cached by the old version keeps rendering acceptably — readable and usable, though not always pixel-perfect.</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="LocalSettings.php">LocalSettings.php</span></div><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$wgCitizenCompat </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></div><div class="tip custom-block"><p class="custom-block-title">How far back it reaches</p><p>The flag covers HTML generated by versions up to <strong>6 minor releases</strong> back, which is roughly six months of releases at the current pace. The window is measured on the HTML, not on the size of your upgrade jump: what matters is the oldest version still sitting in your caches, and that is decided by your longest TTL. A 90-day CDN TTL can hold HTML from outside the window even on a one-release upgrade, and anything older than the window needs a <a href="#clearing-the-old-cache">cache clear</a>.</p></div><h3 id="_2-upgrade-citizen" tabindex="-1">2. Upgrade Citizen <a class="header-anchor" href="#_2-upgrade-citizen" aria-label="Permalink to “2. Upgrade Citizen”">​</a></h3><p>Deploy the new version the way you normally would.</p><h3 id="_3-purge-if-the-release-asked-for-it" tabindex="-1">3. Purge, if the release asked for it <a class="header-anchor" href="#_3-purge-if-the-release-asked-for-it" aria-label="Permalink to “3. Purge, if the release asked for it”">​</a></h3><p>If the status is <code>purge required</code>, <a href="#clearing-the-old-cache">clear the cache</a> now — after the upgrade, not before. Purging first achieves nothing, because those pages re-cache under the old version within minutes.</p><h3 id="_4-let-the-old-cache-go" tabindex="-1">4. Let the old cache go <a class="header-anchor" href="#_4-let-the-old-cache-go" aria-label="Permalink to “4. Let the old cache go”">​</a></h3><p>Stale pages last as long as the longest of these, counted from the deploy:</p><ul><li><code>$wgParserCacheExpireTime</code> — the parser cache. One day by default.</li><li><code>$wgCdnMaxAge</code> — how long a CDN or Varnish may serve a page. Five hours by default, though your CDN&#39;s own configuration can override it.</li><li><code>$wgUseFileCache</code> has no expiry at all: entries stay until the page is edited or <code>$wgCacheEpoch</code> moves past them.</li></ul><p>Leave the flag on for that long, or <a href="#clearing-the-old-cache">clear the cache</a> if you would rather not wait.</p><div class="tip custom-block"><p class="custom-block-title">Saving <code>LocalSettings.php</code> already moves the epoch</p><p>On a default wiki, <code>$wgInvalidateCacheOnLocalSettingsChange</code> pushes <code>$wgCacheEpoch</code> to the file&#39;s modification time. Save or <code>touch</code><code>LocalSettings.php</code> after the upgrade and MediaWiki&#39;s own caches turn over from that moment, leaving only your CDN to wait for. Wikis that set that setting to <code>false</code>, or keep their config in a file <code>LocalSettings.php</code> merely includes, do not get this and need to <a href="#move-wgcacheepoch-forward">set the epoch by hand</a>.</p></div><h3 id="_5-turn-the-flag-off" tabindex="-1">5. Turn the flag off <a class="header-anchor" href="#_5-turn-the-flag-off" aria-label="Permalink to “5. Turn the flag off”">​</a></h3><p>Cached HTML carries the generation that rendered it, so you can check rather than guess. Purge any page with <code>?action=purge</code>, view source, and note the <code>data-mw-citizen-html</code> attribute on <code>&lt;html&gt;</code>. Then open a page you know has not been edited since before the upgrade: if its attribute matches, that page is current.</p><p>Once the stale pages are gone, set <code>$wgCitizenCompat = false;</code> again. Leaving it on costs a few kilobytes of extra CSS and nothing else — the compat styles are written not to match current HTML — so wikis that deploy continuously can simply leave it on.</p><h2 id="clearing-the-old-cache" tabindex="-1">Clearing the old cache <a class="header-anchor" href="#clearing-the-old-cache" aria-label="Permalink to “Clearing the old cache”">​</a></h2><p>Just one or two pages looking wrong? Purge those individually with <code>?action=purge</code> and skip the rest of this section.</p><div class="warning custom-block"><p class="custom-block-title">These clear MediaWiki&#39;s own caches</p><p>Nothing here touches a CDN or Varnish in front of your wiki. That needs its own purge, or its TTL to lapse — which is usually what decides when you can turn the flag off.</p></div><p>If your release is <code>purge required</code>, skip past the first option below: for those pages, waiting means leaving them visibly broken until they expire.</p><h3 id="just-wait" tabindex="-1">Just wait <a class="header-anchor" href="#just-wait" aria-label="Permalink to “Just wait”">​</a></h3><p>Usually the right answer. Cached pages expire on their own, and the flag keeps them readable until they do, so there is nothing to run and no re-parse spike to absorb.</p><h3 id="move-wgcacheepoch-forward" tabindex="-1">Move <code>$wgCacheEpoch</code> forward <a class="header-anchor" href="#move-wgcacheepoch-forward" aria-label="Permalink to “Move $wgCacheEpoch forward”">​</a></h3><p>Anything cached before the epoch is treated as stale, so pages re-parse as people visit them rather than all at once. This is also what clears the file cache, which has no expiry of its own, and it works with any parser cache backend rather than only <code>CACHE_DB</code>. Most wikis get it for free from saving <code>LocalSettings.php</code> (see step 4) — set it by hand if yours does not.</p><div class="vp-code-block-title"><div class="vp-code-block-title-bar"><span class="vp-code-block-title-text" data-title="LocalSettings.php">LocalSettings.php</span></div><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// The moment you upgraded, as a UTC MediaWiki timestamp</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$wgCacheEpoch </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;20260729120000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>This invalidates every page on the wiki, not just the ones Citizen&#39;s styles affect, so your whole hot set re-parses on first view. On a large or template-heavy wiki, pick a quiet window. The timestamp is UTC — a local one silently leaves hours of stale cache behind.</p></div><h3 id="purge-the-parser-cache" tabindex="-1">Purge the parser cache <a class="header-anchor" href="#purge-the-parser-cache" aria-label="Permalink to “Purge the parser cache”">​</a></h3><p>Deletes entries outright, oldest first. <code>--age</code> is in seconds counted back from now, so pace a large purge by re-running it with a smaller age each day:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Older than a week, then older than three days, then older than a day</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maintenance/run.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purgeParserCache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 604800</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maintenance/run.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purgeParserCache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 259200</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maintenance/run.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purgeParserCache</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --age</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 86400</span></span></code></pre></div><p>Add <code>--dry-run</code> to see what a run would delete before you commit to it — the deletion cannot be undone — and <code>--msleep 500</code> to go easy on the database. If you lowered <code>$wgParserCacheExpireTime</code> per <a href="#plan-ahead">plan ahead</a>, use <code>--expiredate</code> instead: <code>--age</code> assumes that setting has not changed.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><a href="https://www.mediawiki.org/wiki/Manual:PurgeParserCache.php" target="_blank" rel="noreferrer"><code>purgeParserCache.php</code></a> only works when the parser cache is in the database — <code>CACHE_DB</code>, which is the default. If yours is in Memcached or Redis it stops with an error, so use <code>$wgCacheEpoch</code> instead.</p></div>`,39)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};